class Gradebook:
    def __init__(self) -> None:
        # Maps assignment name to its weight
        self._assignments: dict[str, float] = {}
        # Maps student name to a dict of {assignment_name: grade}
        self._grades: dict[str, dict[str, float]] = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        self._assignments[name] = float(weight)

    def record(self, student: str, assignment: str, grade: float) -> None:
        grade = float(grade)
        if not (2.0 <= grade <= 5.0):
            raise ValueError(f"Grade {grade} is outside the allowed scale of 2.0 to 5.0.")

        if student not in self._grades:
            self._grades[student] = {}
        self._grades[student][assignment] = grade

    def average(self, student: str) -> float:
        total_weight = sum(self._assignments.values())
        if total_weight == 0:
            return 0.0

        student_grades = self._grades.get(student, {})
        weighted_sum = sum(
            student_grades.get(name, 2.0) * weight
            for name, weight in self._assignments.items()
        )

        return round(weighted_sum / total_weight, 2)
